package com.portfolio.assetory.order.dto.response;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;import com.portfolio.assetory.order.domain.Order;import com.portfolio.assetory.order.domain.OrderItem;
public record OrderListResponse(List<Summary> orders,int page,int totalPages){public static OrderListResponse from(org.springframework.data.domain.Page<Order> page,java.util.Map<Long,List<OrderItem>> items){return new OrderListResponse(page.getContent().stream().map(o->Summary.from(o,items.get(o.getId()))).toList(),page.getNumber(),page.getTotalPages());}public record Summary(Long orderId,String orderNumber,String representativeProductName,int itemCount,BigDecimal totalPrice,String status,LocalDateTime orderedAt){static Summary from(Order o,List<OrderItem> items){return new Summary(o.getId(),o.getOrderNumber(),items.get(0).getProductName(),items.size(),o.getTotalAmount(),o.getStatus().name(),o.getCreatedAt());}}}
